def main():
    for lang, values in T.items():
        assert len(values) == len(KEYS), f'{lang}: {len(values)} strings, expected {len(KEYS)}'
        strings = dict(zip(KEYS, values))
        assert len(EXTRA[lang]) == len(EXTRA_KEYS), f'{lang}: extra strings'
        strings.update(dict(zip(EXTRA_KEYS, EXTRA[lang])))
        # Product name, not translated; the setup texts name the keyboard as the system lists it.
        name = re.escape(strings['app_name'])
        for key in ('setup_select_desc', 'setup_full_desc'):
            text = re.sub(r'([«“„”"‘’]\s?)' + name + r'(\s?[»”“"‘’])', r'\1gBart\2', strings[key])
            strings[key] = text.replace(f'› {strings["app_name"]} ›', '› gBart ›')
        strings['app_name'] = 'gBart'
        strings['EntryAbility_label'] = strings['app_name']
        strings['ime_label'] = strings['app_name']
        strings['ime_desc'] = strings['module_desc']
        folder = os.path.join(RES, lang, 'element')
        os.makedirs(folder, exist_ok=True)
        with open(os.path.join(folder, 'string.json'), 'w', encoding='utf-8') as f:
            json.dump({'string': [{'name': k, 'value': v} for k, v in strings.items()]}, f, ensure_ascii=False,
                      indent=2)
        app_folder = os.path.join(ROOT, 'AppScope', 'resources', lang, 'element')
        os.makedirs(app_folder, exist_ok=True)
        with open(os.path.join(app_folder, 'string.json'), 'w', encoding='utf-8') as f:
            json.dump({'string': [{'name': 'app_name', 'value': strings['app_name']}]}, f, ensure_ascii=False, indent=2)


if __name__ == '__main__':
    main()
